package org.viridexa.api.protection;
import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TurnstileTransportTest {
 @Test void wireUsesPostBodyAndRejectsOversizedResponses()throws Exception{var request=new AtomicReference<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/verify",e->{request.set(e.getRequestMethod()+" "+e.getRequestURI()+" "+new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));byte[] body="x".repeat(17000).getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,body.length);e.getResponseBody().write(body);e.close();});server.start();try{var transport=new TurnstileTransport(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/verify"));assertThrows(Exception.class,()->transport.verify("private-secret","token+slash/",2));assertTrue(request.get().startsWith("POST /verify "));assertTrue(request.get().contains("secret=private-secret&response=token%2Bslash%2F"));assertFalse(request.get().contains("/verify?"));}finally{server.stop(0);}}
 @Test void deadlineAlsoCancelsAStalledResponseBody()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/verify",e->{e.sendResponseHeaders(200,0);try{Thread.sleep(1600);e.getResponseBody().write("{}".getBytes(StandardCharsets.UTF_8));}catch(Exception ignored){}finally{e.close();}});server.start();try{var transport=new TurnstileTransport(URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/verify"));long began=System.nanoTime();assertThrows(Exception.class,()->transport.verify("secret","token",1));assertTrue(Duration.ofNanos(System.nanoTime()-began).toMillis()<1500);}finally{server.stop(0);}}
}
